sys_script_client.script:
function onLoad() {
    // Only run for leave_user role
    if (g_user.hasRole('x_1800027_leve_sys.leave_user')) {
        try {
            // Check if country field exists
            var countryField = g_form.getElement('country');

            if (!countryField) {
                // Get employee's country from their profile
                var ga = new GlideAjax('x_1800027_leve_sys.UserProfileUtil');
                ga.addParam('sysparm_name', 'getUserCountry');
                ga.addParam('sysparm_user_id', g_form.getReference('employee').sys_id);

                ga.getXML(function(response) {
                    var countryValue = response.responseXML.documentElement.getAttribute('answer');

                    // Add country as a hidden field and set its value
                    g_form.addInfoMessage("Country set to: " + countryValue);

                    // Store country value in a hidden variable
                    g_scratchpad.country = countryValue;

                    // Add a custom field to display country
                    var labelElement = document.createElement('div');
                    labelElement.innerHTML = '<div class="form-group"><label class="col-sm-4 control-label">Country</label>' +
                                            '<div class="col-sm-8"><p class="form-control-static">' + countryValue + '</p></div></div>';

                    // Find a good place to insert it
                    var sections = document.getElementsByClassName('section-content');
                    if (sections && sections.length > 0) {
                        sections[0].appendChild(labelElement);
                    }
                });
            }
        } catch (e) {
            console.error("Error adding country field: " + e);
        }
    }
}
